<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Journey to Apple 2030</title>
<style>
  body {
    background-color: #000;
    color: #fff;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    margin: 0;
    padding: 0;
    overflow-x: hidden;
  }

  header {
    display: flex;
    justify-content: space-between;
    font-size: 12px;
    color: #a1a1a6;
    padding: 30px 50px;
  }

  .nav-left {
    display: flex;
    flex-direction: column;
  }

  .nav-main {
    display: flex;
    gap: 25px;
  }

  .nav-main .active {
    color: #fff;
    font-weight: 600;
  }

  .nav-sub {
    display: flex;
    flex-direction: column;
    margin-top: 8px;
    padding-left: 185px; /* Aligns under Environmental Initiatives */
    gap: 4px;
  }

  .nav-sub span {
    color: #fff;
    font-weight: 600;
  }

  .main-title {
    font-size: 56px;
    font-weight: 700;
    margin: 40px 50px 20px 50px;
    letter-spacing: -1px;
  }

  .timeline-area {
    position: relative;
    height: 750px;
    width: 100%;
    max-width: 1800px;
    margin: 0 auto;
    margin-top: 20px;
  }

  .gray-box {
    position: absolute;
    top: 40px;
    bottom: 40px;
    left: 26%;
    width: 40%;
    background-color: #222;
    border-radius: 16px;
    z-index: 0;
  }

  .section-title {
    position: absolute;
    top: 70px;
    font-size: 32px;
    font-weight: 700;
    line-height: 1.1;
    z-index: 1;
  }

  .timeline-line {
    position: absolute;
    top: 50%;
    height: 0;
    z-index: 1;
  }

  .timeline-line.solid {
    width: 67%;
    border-top: 2px solid #34c759;
  }

  .timeline-line.dashed {
    left: 67%;
    width: 33%;
    border-top: 2px dashed #34c759;
  }

  .node {
    position: absolute;
    top: 50%;
    z-index: 2;
  }

  .dot {
    width: 8px;
    height: 8px;
    background-color: #fff;
    border-radius: 50%;
    position: absolute;
    top: -4px;
    left: -4px;
  }

  .year {
    position: absolute;
    color: #fff;
    font-weight: 700;
    font-size: 14px;
    bottom: 15px;
    left: -15px;
  }

  .content-up, .content-down {
    position: absolute;
    left: 0;
  }

  .content-up { bottom: 0; }
  .content-down { top: 0; }

  .vline {
    position: absolute;
    left: 0;
    width: 1px;
    background-color: #666;
  }

  .content-up .vline { bottom: 0; }
  .content-down .vline { top: 0; }

  .text {
    position: absolute;
    left: 15px;
    font-size: 13px;
    line-height: 1.5;
    color: #a1a1a6;
  }

  .text b {
    color: #fff;
    font-weight: 600;
  }

  .green {
    color: #34c759;
    font-weight: 600;
  }

  .green-large {
    color: #34c759;
    font-size: 24px;
    font-weight: 700;
  }

  sup {
    font-size: 9px;
    vertical-align: super;
  }
</style>
</head>
<body>

<header>
  <div class="nav-left">
    <div class="nav-main">
      <span>Contents</span>
      <span>Introduction</span>
      <span class="active">Environmental Initiatives</span>
      <span>Engagement and Advocacy</span>
      <span>Data</span>
      <span>Appendix</span>
    </div>
    <div class="nav-sub">
      <span>Apple 2030</span>
      <span>Resources</span>
      <span>Smarter Chemistry</span>
    </div>
  </div>
  <div class="nav-right">
    2024 Environmental Progress Report &nbsp;&nbsp; 11
  </div>
</header>

<h1 class="main-title">Journey to Apple 2030</h1>

<div class="timeline-area">

  <!-- Background Box -->
  <div class="gray-box"></div>

  <!-- Section Titles -->
  <div class="section-title" style="left: 3%;">Where<br>we've been</div>
  <div class="section-title" style="left: 28%;">2023<br>activities</div>
  <div class="section-title" style="left: 68%;">Where<br>we're going</div>

  <!-- Horizontal Lines -->
  <div class="timeline-line solid"></div>
  <div class="timeline-line dashed"></div>

  <!-- 2015 -->
  <div class="node" style="left: 3%;">
    <div class="year">2015</div>
    <div class="dot"></div>
    <div class="content-down">
      <div class="vline" style="height: 180px;"></div>
      <div class="text" style="top: 180px; width: 140px;">
        <span class="green">Launched</span><br>
        Supplier Clean<br>
        Energy and Energy<br>
        Efficiency Programs<br>
        established to partner<br>
        with global suppliers<br>
        to reduce the energy<br>
        used to manufacture<br>
        Apple products
      </div>
    </div>
  </div>

  <!-- 2018 -->
  <div class="node" style="left: 13%;">
    <div class="year">2018</div>
    <div class="dot"></div>
    <div class="content-down">
      <div class="vline" style="height: 180px;"></div>
      <div class="text" style="top: 180px; width: 130px;">
        <span class="green">Achieved</span><br>
        <b>100% renewable<br>
        electricity</b><br>
        generated or<br>
        sourced for<br>
        our corporate<br>
        operations
      </div>
    </div>
  </div>

  <!-- 2020 -->
  <div class="node" style="left: 20%;">
    <div class="year">2020</div>
    <div class="dot"></div>
    <div class="content-up">
      <div class="vline" style="height: 150px;"></div>
      <div class="text" style="top: -150px; left: -135px; width: 120px;">
        <span class="green">Launched</span><br>
        <b>Restore Fund</b><br>
        to advance<br>
        nature-based<br>
        carbon removal<br>
        projects
      </div>
    </div>
  </div>

  <!-- 2021 -->
  <div class="node" style="left: 23%;">
    <div class="year">2021</div>
    <div class="dot"></div>
    <div class="content-down">
      <div class="vline" style="height: 180px;"></div>
      <div class="text" style="top: 180px; width: 140px;">
        <span class="green">Achieved</span><br>
        <b>Carbon<br>
        neutrality</b><br>
        for our corporate<br>
        operations and<br>
        announced<br>
        2030 targets
      </div>
    </div>
  </div>

  <!-- 2022 -->
  <div class="node" style="left: 27%;">
    <div class="year">2022</div>
    <div class="dot"></div>
  </div>

  <!-- Box Dot 1 (22%) -->
  <div class="node" style="left: 30%;">
    <div class="dot"></div>
    <div class="content-down">
      <div class="vline" style="height: 150px;"></div>
      <div class="text" style="top: 150px; width: 110px;">
        <b>22%</b><br>
        of the material<br>
        shipped in<br>
        products came<br>
        from recycled<br>
        or renewable<br>
        sources<sup>19</sup>
      </div>
    </div>
  </div>

  <!-- Box Dot 2 (12.8M) -->
  <div class="node" style="left: 36%;">
    <div class="dot"></div>
    <div class="content-up">
      <div class="vline" style="height: 150px;"></div>
      <div class="text" style="top: -150px; width: 130px;">
        <b>12.8M</b><br>
        devices and<br>
        accessories sent<br>
        to new users<br>
        for reuse from<br>
        programs like<br>
        Apple Trade In<br>
        and AppleCare
      </div>
    </div>
  </div>

  <!-- Box Dot 3 (20%) -->
  <div class="node" style="left: 42%;">
    <div class="dot"></div>
    <div class="content-down">
      <div class="vline" style="height: 150px;"></div>
      <div class="text" style="top: 150px; width: 120px;">
        <b>20%</b><br>
        reduction in<br>
        emissions from<br>
        transporting<br>
        products<br>
        compared<br>
        to 2022
      </div>
    </div>
  </div>

  <!-- Box Dot 4 (70%+) -->
  <div class="node" style="left: 48%;">
    <div class="dot"></div>
    <div class="content-up">
      <div class="vline" style="height: 150px;"></div>
      <div class="text" style="top: -150px; width: 120px;">
        <b>70%+</b><br>
        reduction<br>
        in average<br>
        product energy<br>
        use since 2008
      </div>
    </div>
  </div>

  <!-- Box Dot 5 (320+) -->
  <div class="node" style="left: 54%;">
    <div class="dot"></div>
    <div class="content-down">
      <div class="vline" style="height: 150px;"></div>
      <div class="text" style="top: 150px; width: 140px;">
        <b>320+</b><br>
        suppliers are<br>
        committed to<br>
        using 100%<br>
        renewable energy<br>
        for all Apple-<br>
        related production<br>
        by 2030
      </div>
    </div>
  </div>

  <!-- Box Dot 6 (Codified) -->
  <div class="node" style="left: 60%;">
    <div class="dot"></div>
    <div class="content-up">
      <div class="vline" style="height: 150px;"></div>
      <div class="text" style="top: -150px; width: 140px;">
        <span class="green">Codified</span><br>
        <b>100% renewable<br>
        energy</b><br>
        mandate added<br>
        to our Supplier<br>
        Code of Conduct<br>
        applicable to all<br>
        direct suppliers for<br>
        the manufacture of<br>
        Apple products
      </div>
    </div>
  </div>

  <!-- 2023 -->
  <div class="node" style="left: 67%;">
    <div class="year">2023</div>
    <div class="dot"></div>
  </div>

  <!-- 2025 -->
  <div class="node" style="left: 73%;">
    <div class="year">2025</div>
    <div class="dot"></div>
    <div class="content-up">
      <div class="vline" style="height: 80px;"></div>
      <div class="text" style="top: -80px; width: 160px;">
        <span class="green">Goal</span><br>
        <b>Transition</b><br>
        to 100% fiber-based<br>
        packaging by 2025<sup>20</sup>
      </div>
    </div>
    <div class="content-down">
      <div class="vline" style="height: 50px;"></div>
      <div class="text" style="top: 50px; width: 240px;">
        <span class="green">Goal</span><br>
        <b>Use</b><br>
        100% recycled cobalt in all<br>
        Apple-designed batteries<sup>21</sup><br><br>
        100% recycled tin soldering<br>
        and 100% recycled gold<br>
        plating in all Apple-designed<br>
        rigid and flexible printed<br>
        circuit boards<sup>22</sup><br><br>
        100% recycled rare earth<br>
        elements in all magnets<br>
        across all products<sup>23</sup>
      </div>
    </div>
  </div>

  <!-- 2030 -->
  <div class="node" style="left: 90%;">
    <div class="year">2030</div>
    <div class="dot"></div>
    <div class="content-up">
      <div class="text" style="top: -180px; left: 0; width: 200px;">
        <span class="green-large">Apple 2030</span><br>
        <span style="font-size: 24px; font-weight: 700; color: #fff; line-height: 1.2; display: block; margin-top: 5px;">
          To be carbon<br>
          neutral for<br>
          our entire<br>
          footprint<br>
          by 2030
        </span>
      </div>
    </div>
  </div>

</div>

</body>
</html>
```
